/**
 * Minimal ambient declarations for the CommonJS dependencies of the JSON AST port.
 *
 * `asty-astq`, `pegjs-otf` and `pegjs-util` ship without type definitions, so only the
 * surface used by `./json-ast.ts` is declared here. All type assertions for these
 * modules stay in this file and inside `./json-ast.ts`; the public API of the module is
 * expressed with `JsonAstNode`/`AstNodePos` from `./types` only.
 */

declare module 'asty-astq' {
  /**
   * An AST factory: `new ASTY()` yields a context whose `create` mints new nodes.
   *
   * `asty-astq` is `ASTy` mixed with the ASTq query engine, so the returned nodes also
   * provide `query`; the node surface is described by `./types`.
   */
  export default class ASTY {
    /** Create a new AST node from `asty` create arguments (`type`, `attrs?`, `childs?`). */
    create(...args: unknown[]): import('./types').JsonAstNode;
  }
}

declare module 'pegjs-otf' {
  /** A parser generated by Peggy (the subset used by `pegjs-util`). */
  export interface PegjsParser {
    /** Parse input text with the grammar of the parser. */
    parse(input: string, options?: Record<string, unknown>): unknown;
    /** Error class thrown on a syntax error; `pegjs-util` uses it to classify failures. */
    SyntaxError: new (message: string, expected: unknown, found: unknown, location: unknown) => Error;
  }

  /** Options of `generateFromFile`, forwarded to Peggy `generate`. */
  export interface PegjsGenerateOptions {
    optimize?: 'speed' | 'size';
    trace?: boolean;
  }

  const PEG: {
    /** Read the grammar from `filename` and generate a parser from it. */
    generateFromFile(filename: string, options?: PegjsGenerateOptions): PegjsParser;
  };

  export default PEG;
}

declare module 'pegjs-util' {
  /** A generated parser as far as `parse` uses it. */
  export interface PegjsUtilParser {
    parse(input: string, options?: Record<string, unknown>): unknown;
    /** The parser error class, used by `parse` to recognize syntax errors. */
    SyntaxError: unknown;
  }

  /** Source excerpt around a parse error. */
  export interface PegjsUtilErrorExcerpt {
    prolog: string;
    token: string;
    epilog: string;
  }

  /** Parse error descriptor produced by `parse`. */
  export interface PegjsUtilParseError {
    line: number;
    column: number;
    message: string;
    found: unknown;
    expected: unknown;
    location: PegjsUtilErrorExcerpt;
  }

  /** Result of `parse`: `ast` is `null` on a failure, `error` is `null` on success. */
  export interface PegjsUtilParseResult<T> {
    ast: T | null;
    error: PegjsUtilParseError | null;
  }

  /** Options of `parse`. */
  export interface PegjsUtilParseOptions<T> {
    /** Grammar rule to start with. */
    startRule?: string;
    /** AST node factory: receives the node position and the arguments of `ast(...)`. */
    makeAST?: (line: number, column: number, offset: number, args: string[]) => T;
    [option: string]: unknown;
  }

  export interface PegjsUtil {
    /** Parse `txt` with `parser`, capturing syntax errors in the result object. */
    parse<T>(parser: PegjsUtilParser, txt: string, options?: PegjsUtilParseOptions<T>): PegjsUtilParseResult<T>;
    /** Render a human readable message (line, column, excerpt) for a parse error. */
    errorMessage(error: PegjsUtilParseError, noFinalNewline?: boolean): string;
  }

  const PEGUtil: PegjsUtil;

  export default PEGUtil;
}
